import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export const holidaysKey = (sheet: string) => ['holidays', sheet] as const;

export const holidaysPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/holidays`;

/** The sheet's holidays (yyyy-MM-dd), earliest first. */
export function useHolidays(sheet: string) {
  return useQuery({
    queryKey: holidaysKey(sheet),
    queryFn: () => getJson<string[]>(holidaysPath(sheet)),
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { holidaysKey, holidaysPath, useHolidays } from './holidays';

// The sheet's holidays, and a form that adds a date to them. A claim's due-by, fixed when the claim is added, is
// moved past the holidays on the sheet then; adding a holiday works out again the due-by of every claim not SETTLED
// or VOID due on or after it, which may move the sheet's figures.
function Holidays({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: holidays = [] } = useHolidays(sheet);
  const [date, setDate] = useState('');

  const add = useMutation({
    mutationFn: (body: { date: string }) => postJson<string[]>(byUser(holidaysPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(holidaysKey(sheet), updated);
      setDate('');
      // Due-by dates, and everything figured from them, may have moved: re-read the rest of the sheet.
      void queryClient.invalidateQueries({
        predicate: (q) => q.queryKey.includes(sheet) && q.queryKey[0] !== 'holidays' && q.queryKey[0] !== 'sheet',
      });
    },
  });
  const send = useSubmitOnce(add);

  const change = (next: string) => {
    setDate(next);
    add.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a date that is not valid or is already on the list.
    send({ date });
  };

  return (
    <section>
      <h2>Holidays</h2>
      <form onSubmit={submit}>
        <label>
          Date{' '}
          <input
            data-testid="holiday-date"
            placeholder="yyyy-mm-dd"
            value={date}
            onChange={(e) => change(e.target.value)}
          />
        </label>{' '}
        <button type="submit" data-testid="holiday-add" disabled={add.isPending}>
          Add holiday
        </button>
        {add.isError && (
          <span data-testid="holiday-error" role="alert">
            {' '}A holiday needs a valid date not already on the list.
          </span>
        )}
      </form>
      <ul>
        {holidays.map((d) => (
          <li key={d} data-testid={`holiday-row-${d}`}>
            {d}
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 9, Component: Holidays });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a form tell one refusal from another. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The date the screen shows the sheet as of (search param `asof`), or '' when it shows it as it is now. */
export function currentAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  return raw.replace(/^"|"$/g, '');
}

/** Every request carries the screen's as-of date: the server answers each read as the sheet stood then, and
 *  refuses every write while it is set. */
function withAsOf(path: string): string {
  const asOf = currentAsOf();
  return asOf ? `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}` : path;
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(withAsOf(path), init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

